function i(t){return String(t).padStart(2,"0")}function c(t){if(!t)return null;const e=typeof t=="string"?new Date(t):t;return Number.isNaN(e.getTime())?null:`${e.getFullYear()}-${i(e.getMonth()+1)}-${i(e.getDate())}`}function f(t){const e=typeof t=="string"&&/^\d{4}-\d{2}-\d{2}$/.test(t)?t:c(t);return e?`${e}T00:00:00.000Z`:null}function l(t=7,e=!0){const o=[],n=new Date,s=e?1:0;for(let r=s;r<t+s;r++){const a=new Date(n.getFullYear(),n.getMonth(),n.getDate()+r),u=a.toLocaleDateString("id-ID",{weekday:"short",day:"numeric",month:"short"}),d=c(a),g=f(d);o.push({label:u,value:g})}return o}export{c as a,l as g,f as t};
